import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/Checkout.css";

const Checkout = () => {
  const userId = sessionStorage.getItem("userId");
  const navigate = useNavigate();
  const [cartItems, setCartItems] = useState([]);
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    address: "",
    city: "",
    state: "",
    zip: "",
    country: ""
  });
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/cart/user/${userId}`)
      .then((res) => res.json())
      .then((items) => {
        setCartItems(items);
        const subtotal = items.reduce((sum, item) => sum + parseFloat(item.price), 0);
        const tax = subtotal * 0.08;
        const shipping = Math.floor(Math.random() * 5) + 3;
        setTotal(subtotal + tax + shipping);
      })
      .catch((err) => console.error("Failed to load cart items:", err));
  }, [userId]);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handlePlaceOrder = async () => {
    setLoading(true);

    const payload = {
      user_id: parseInt(userId),
      items: cartItems.map((item) => ({
        listing_id: Number(item.id),
        seller_id: Number(item.user_id || item.seller_id),
        price: parseFloat(item.price)
      })),
      total,
      shipping_info: form,
      buyer_name: form.name,
      buyer_email: form.email,
      buyer_phone: form.phone
    };

    try {
      const res = await fetch(`${API_BASE_URL}/api/orders`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });

      if (res.ok) {
        await fetch(`${API_BASE_URL}/api/cart/clear/${userId}`, { method: "DELETE" });
        navigate("/my-orders");
      } else {
        const data = await res.json();
        alert("❌ Failed to place order: " + data.message);
      }
    } catch (error) {
      console.error("Checkout error:", error);
      alert("❌ Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="checkout-wrapper">
      <Navbar />
      <div className="checkout-main">
        <h2>Checkout</h2>
        <div className="checkout-content">
          <form className="shipping-form">
            {Object.entries(form).map(([field, value]) => (
              <input
                key={field}
                type="text"
                name={field}
                placeholder={field.charAt(0).toUpperCase() + field.slice(1)}
                value={value}
                onChange={handleChange}
              />
            ))}
          </form>
          <div className="summary-box">
            <h3>Payment Summary</h3>
            <p>Total: ${total.toFixed(2)}</p>
            <button className="order-btn" onClick={handlePlaceOrder} disabled={loading}>
              {loading ? "Placing Order..." : "Simulate Payment & Place Order"}
            </button>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Checkout;
